                     r1 = t3c_excits(idet,1); r2 = t3c_excits(idet,2); r3 = t3c_excits(idet,3); r4 = t3c_excits(idet,4); r5 = t3c_excits(idet,5); r6 = t3c_excits(idet,6);
                     jdet = 1*(idet-1)
                     vabb0202_excits(jdet+1,:) = (/r2,r3,r5,r6,r1,r4/); vabb0202_amps(jdet+1) = t3c_amps(idet)
                  end do
                  vdims_vabb0202 = (/nub,nub,nob,nob/); vchain_vabb0202 = (/.false.,.true.,.false.,.true./)
                  call sort_pspace(vabb0202_excits, vabb0202_amps, 1*n3abb, 4, (/1,2,3,4/), vdims_vabb0202, vchain_vabb0202, nblk_vabb0202, key_vabb0202, off_vabb0202)
                  ! view vabb1102: every t3c row once per key placement, key columns first
                  allocate(vabb1102_amps(2*n3abb),vabb1102_excits(2*n3abb,6))
                  do idet = 1, n3abb
                     r1 = t3c_excits(idet,1); r2 = t3c_excits(idet,2); r3 = t3c_excits(idet,3); r4 = t3c_excits(idet,4); r5 = t3c_excits(idet,5); r6 = t3c_excits(idet,6);
                     jdet = 2*(idet-1)
                     vabb1102_excits(jdet+1,:) = (/r1,r2,r5,r6,r3,r4/); vabb1102_amps(jdet+1) = t3c_amps(idet)
                     vabb1102_excits(jdet+2,:) = (/r1,r3,r5,r6,r2,r4/); vabb1102_amps(jdet+2) = -t3c_amps(idet)
                  end do
                  vdims_vabb1102 = (/nua,nub,nob,nob/); vchain_vabb1102 = (/.false.,.false.,.false.,.true./)
                  call sort_pspace(vabb1102_excits, vabb1102_amps, 2*n3abb, 4, (/1,2,3,4/), vdims_vabb1102, vchain_vabb1102, nblk_vabb1102, key_vabb1102, off_vabb1102)
                  ! view vabb0211: every t3c row once per key placement, key columns first
                  allocate(vabb0211_amps(2*n3abb),vabb0211_excits(2*n3abb,6))
                  do idet = 1, n3abb
                     r1 = t3c_excits(idet,1); r2 = t3c_excits(idet,2); r3 = t3c_excits(idet,3); r4 = t3c_excits(idet,4); r5 = t3c_excits(idet,5); r6 = t3c_excits(idet,6);
                     jdet = 2*(idet-1)
                     vabb0211_excits(jdet+1,:) = (/r2,r3,r4,r5,r1,r6/); vabb0211_amps(jdet+1) = t3c_amps(idet)
                     vabb0211_excits(jdet+2,:) = (/r2,r3,r4,r6,r1,r5/); vabb0211_amps(jdet+2) = -t3c_amps(idet)
                  end do
                  vdims_vabb0211 = (/nub,nub,noa,nob/); vchain_vabb0211 = (/.false.,.true.,.false.,.false./)
                  call sort_pspace(vabb0211_excits, vabb0211_amps, 2*n3abb, 4, (/1,2,3,4/), vdims_vabb0211, vchain_vabb0211, nblk_vabb0211, key_vabb0211, off_vabb0211)

                  ! key-major: I3C_vooooo(axyikl) x tbbb(dcbyxj), 3 classes share IX(q)
                  kbat = max(1, min(3, 16777216 / max(1, n4abbb)))
                  do kc0 = 1, 3, kbat
                     kc1 = min(3, kc0 + kbat - 1)
                     nrd = (kc1 - kc0 + 1) * n4abbb
                     allocate(RQ(nrd,5), rp(nrd))
                     RQ(:,5) = 0   ! keeps a one-reader list from looking like the empty sentinel
                     do icls = kc0, kc1
                        ird0 = (icls - kc0) * n4abbb
                        select case (icls)
                        case (1)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,1); RQ(ird0+idet,2) = t4d_excits(idet,5); RQ(ird0+idet,3) = t4d_excits(idet,6); RQ(ird0+idet,4) = t4d_excits(idet,7);
                           end do
                        case (2)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,1); RQ(ird0+idet,2) = t4d_excits(idet,5); RQ(ird0+idet,3) = t4d_excits(idet,6); RQ(ird0+idet,4) = t4d_excits(idet,8);
                           end do
                        case (3)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,1); RQ(ird0+idet,2) = t4d_excits(idet,5); RQ(ird0+idet,3) = t4d_excits(idet,7); RQ(ird0+idet,4) = t4d_excits(idet,8);
                           end do
                        end select
                     end do
                     call index_pspace(RQ, nrd, 4, (/1,2,3,4/), (/nua,noa,nob,nob/), (/.false.,.false.,.false.,.false./), rind)
                     allocate(kmnn(4096), kmslot(4096), kmdk(4096), kmRB(nob*nob,4096))
                     do kch0 = 1, rind%nblock, 4096
                        kch1 = min(rind%nblock, kch0 + 4096 - 1)
                        !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,kdx,idx,xx,yy,ixv,idx2,jdet2,jj2,lk,mark,need,nneed,nn,icls,ird,jr,sgn)
                        allocate(mark(nob,nob), need(2,nob*nob))
                        mark = .false.
                        !$omp do schedule(dynamic,8)
                        do kdx = kch0, kch1
                           nneed = 0
                           do jr = rind%off(kdx), rind%off(kdx+1)-1
                              ird = rind%perm(jr); icls = kc0 + (ird-1)/n4abbb; idet = mod(ird-1, n4abbb) + 1
                              select case (icls)
                              case (1)
                                 b = t4d_excits(idet,2); c = t4d_excits(idet,3); d = t4d_excits(idet,4); l = t4d_excits(idet,8);
                                 idx = pspace_find(key_vbbb31, nblk_vbbb31, pspace_key((/b,c,d,l/), 4, vdims_vbbb31, vchain_vbbb31))
                                 rp(ird) = idx
                                 if (idx/=0) then
                                 do jdet = off_vbbb31(idx), off_vbbb31(idx+1)-1
                                    y = vbbb31_excits(jdet,5); x = vbbb31_excits(jdet,6)
                                    if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                    if (.not. mark(y,x)) then; mark(y,x) = .true.; nneed = nneed + 1; need(1,nneed) = y; need(2,nneed) = x; end if
                                 end do
                                 end if
                              case (2)
                                 b = t4d_excits(idet,2); c = t4d_excits(idet,3); d = t4d_excits(idet,4); k = t4d_excits(idet,7);
                                 idx = pspace_find(key_vbbb31, nblk_vbbb31, pspace_key((/b,c,d,k/), 4, vdims_vbbb31, vchain_vbbb31))
                                 rp(ird) = idx
                                 if (idx/=0) then
                                 do jdet = off_vbbb31(idx), off_vbbb31(idx+1)-1
                                    y = vbbb31_excits(jdet,5); x = vbbb31_excits(jdet,6)
                                    if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                    if (.not. mark(y,x)) then; mark(y,x) = .true.; nneed = nneed + 1; need(1,nneed) = y; need(2,nneed) = x; end if
                                 end do
                                 end if
                              case (3)
                                 b = t4d_excits(idet,2); c = t4d_excits(idet,3); d = t4d_excits(idet,4); j = t4d_excits(idet,6);
                                 idx = pspace_find(key_vbbb31, nblk_vbbb31, pspace_key((/b,c,d,j/), 4, vdims_vbbb31, vchain_vbbb31))
                                 rp(ird) = idx
                                 if (idx/=0) then
                                 do jdet = off_vbbb31(idx), off_vbbb31(idx+1)-1
                                    y = vbbb31_excits(jdet,5); x = vbbb31_excits(jdet,6)
                                    if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                    if (.not. mark(y,x)) then; mark(y,x) = .true.; nneed = nneed + 1; need(1,nneed) = y; need(2,nneed) = x; end if
                                 end do
                                 end if
                              end select
                           end do
                           kmnn(kdx-kch0+1) = nneed
                           do nn = 1, nneed
                              mark(need(1,nn),need(2,nn)) = .false.
                           end do
                        end do
                        !$omp end do
                        deallocate(mark, need)
                        !$omp end parallel
                        ndk = 0
                        do kdx = kch0, kch1
                           kmslot(kdx-kch0+1) = 0
                           if (8*kmnn(kdx-kch0+1) >= nob*nob) then
                              ndk = ndk + 1; kmdk(ndk) = kdx; kmslot(kdx-kch0+1) = ndk
                           end if
                        end do
                        if (ndk > 0) then
                           kmRB(:,1:ndk) = 0.0d0
                           ! IX += -1 * H2C_ooov(xylu) * t2b(auik), one GEMM per value of l
                           allocate(kmcnt(nob+1), kmord(ndk))
                           kmcnt = 0
                           do kmi = 1, ndk
                              kms = RQ(rind%perm(rind%off(kmdk(kmi))),4); kmcnt(kms+1) = kmcnt(kms+1) + 1
                           end do
                           kmcnt(1) = 1
                           do kms = 1, nob
                              kmcnt(kms+1) = kmcnt(kms) + kmcnt(kms+1)
                           end do
                           do kmi = 1, ndk
                              kms = RQ(rind%perm(rind%off(kmdk(kmi))),4); kmord(kmcnt(kms)) = kmi; kmcnt(kms) = kmcnt(kms) + 1
                           end do
                           do kms = nob, 1, -1
                              kmcnt(kms+1) = kmcnt(kms)
                           end do
                           kmcnt(1) = 1
                           !$omp parallel default(shared) private(kmG,kmC,kms,kmk,kmi,kmn,kdx,ird,a,i,k,l,u)
                           allocate(kmG(nub,MAXC), kmC(nob*nob,MAXC))
                           !$omp do schedule(dynamic,1)
                           do kms = 1, nob
                              do kmk = kmcnt(kms), kmcnt(kms+1)-1, MAXC
                                 kmn = min(MAXC, kmcnt(kms+1) - kmk)
                                 do kmi = 1, kmn
                                    kdx = kmdk(kmord(kmk+kmi-1)); ird = rind%perm(rind%off(kdx))
                                    a = RQ(ird,1); i = RQ(ird,2); k = RQ(ird,3); l = RQ(ird,4);
                                    do u = 1, nub
                                       kmG(u,kmi) = t2b(a,u,i,k)
                                    end do
                                 end do
                                 call km_gemm(nob*nob, kmn, nub, -1d0, H2C_ooov_0132(1,1,1,kms), kmG, kmC)
                                 do kmi = 1, kmn
                                    kmRB(:,kmord(kmk+kmi-1)) = kmRB(:,kmord(kmk+kmi-1)) + kmC(:,kmi)
                                 end do
                              end do
                           end do
                           !$omp end do
                           deallocate(kmG, kmC)
                           !$omp end parallel
                           deallocate(kmcnt, kmord)
                           ! IX += +1 * H2C_ooov(xyku) * t2b(auil), one GEMM per value of k
                           allocate(kmcnt(nob+1), kmord(ndk))
                           kmcnt = 0
                           do kmi = 1, ndk
                              kms = RQ(rind%perm(rind%off(kmdk(kmi))),3); kmcnt(kms+1) = kmcnt(kms+1) + 1
                           end do
                           kmcnt(1) = 1
                           do kms = 1, nob
                              kmcnt(kms+1) = kmcnt(kms) + kmcnt(kms+1)
                           end do
                           do kmi = 1, ndk
                              kms = RQ(rind%perm(rind%off(kmdk(kmi))),3); kmord(kmcnt(kms)) = kmi; kmcnt(kms) = kmcnt(kms) + 1
                           end do
                           do kms = nob, 1, -1
                              kmcnt(kms+1) = kmcnt(kms)
                           end do
                           kmcnt(1) = 1
                           !$omp parallel default(shared) private(kmG,kmC,kms,kmk,kmi,kmn,kdx,ird,a,i,k,l,u)
                           allocate(kmG(nub,MAXC), kmC(nob*nob,MAXC))
                           !$omp do schedule(dynamic,1)
                           do kms = 1, nob
                              do kmk = kmcnt(kms), kmcnt(kms+1)-1, MAXC
                                 kmn = min(MAXC, kmcnt(kms+1) - kmk)
                                 do kmi = 1, kmn
                                    kdx = kmdk(kmord(kmk+kmi-1)); ird = rind%perm(rind%off(kdx))
                                    a = RQ(ird,1); i = RQ(ird,2); k = RQ(ird,3); l = RQ(ird,4);
                                    do u = 1, nub
                                       kmG(u,kmi) = t2b(a,u,i,l)
                                    end do
                                 end do
                                 call km_gemm(nob*nob, kmn, nub, 1d0, H2C_ooov_0132(1,1,1,kms), kmG, kmC)
                                 do kmi = 1, kmn
                                    kmRB(:,kmord(kmk+kmi-1)) = kmRB(:,kmord(kmk+kmi-1)) + kmC(:,kmi)
                                 end do
                              end do
                           end do
                           !$omp end do
                           deallocate(kmG, kmC)
                           !$omp end parallel
                           deallocate(kmcnt, kmord)
                        end if
                        !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,kdx,idx,xx,yy,ixv,idx2,jdet2,jj2,lk,mark,need,nneed,nn,icls,ird,jr,sgn)
                        allocate(IX(nob,nob), mark(nob,nob), need(2,nob*nob))
                        mark = .false.
                        !$omp do schedule(dynamic,8)
                        do kdx = kch0, kch1
                           nneed = 0
                           if (kmslot(kdx-kch0+1) == 0) then
                              nneed = 0
                              do jr = rind%off(kdx), rind%off(kdx+1)-1
                                 ird = rind%perm(jr); icls = kc0 + (ird-1)/n4abbb; idet = mod(ird-1, n4abbb) + 1
                                 select case (icls)
                                 case (1)
                                    b = t4d_excits(idet,2); c = t4d_excits(idet,3); d = t4d_excits(idet,4); l = t4d_excits(idet,8);
                                    idx = pspace_find(key_vbbb31, nblk_vbbb31, pspace_key((/b,c,d,l/), 4, vdims_vbbb31, vchain_vbbb31))
                                    rp(ird) = idx
                                    if (idx/=0) then
                                    do jdet = off_vbbb31(idx), off_vbbb31(idx+1)-1
                                       y = vbbb31_excits(jdet,5); x = vbbb31_excits(jdet,6)
                                       if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                       if (.not. mark(y,x)) then; mark(y,x) = .true.; nneed = nneed + 1; need(1,nneed) = y; need(2,nneed) = x; end if
                                    end do
                                    end if
                                 case (2)
                                    b = t4d_excits(idet,2); c = t4d_excits(idet,3); d = t4d_excits(idet,4); k = t4d_excits(idet,7);
                                    idx = pspace_find(key_vbbb31, nblk_vbbb31, pspace_key((/b,c,d,k/), 4, vdims_vbbb31, vchain_vbbb31))
                                    rp(ird) = idx
                                    if (idx/=0) then
                                    do jdet = off_vbbb31(idx), off_vbbb31(idx+1)-1
                                       y = vbbb31_excits(jdet,5); x = vbbb31_excits(jdet,6)
                                       if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                       if (.not. mark(y,x)) then; mark(y,x) = .true.; nneed = nneed + 1; need(1,nneed) = y; need(2,nneed) = x; end if
                                    end do
                                    end if
                                 case (3)
                                    b = t4d_excits(idet,2); c = t4d_excits(idet,3); d = t4d_excits(idet,4); j = t4d_excits(idet,6);
                                    idx = pspace_find(key_vbbb31, nblk_vbbb31, pspace_key((/b,c,d,j/), 4, vdims_vbbb31, vchain_vbbb31))
                                    rp(ird) = idx
                                    if (idx/=0) then
                                    do jdet = off_vbbb31(idx), off_vbbb31(idx+1)-1
                                       y = vbbb31_excits(jdet,5); x = vbbb31_excits(jdet,6)
                                       if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                       if (.not. mark(y,x)) then; mark(y,x) = .true.; nneed = nneed + 1; need(1,nneed) = y; need(2,nneed) = x; end if
                                    end do
                                    end if
                                 end select
                              end do
                           end if
                           ird = rind%perm(rind%off(kdx))
                           a = RQ(ird,1); i = RQ(ird,2); k = RQ(ird,3); l = RQ(ird,4);
                           lk(1) = pspace_find_sorted(key_vabb1012, nblk_vabb1012, (/a,i,k,l/), 4, vdims_vabb1012, vchain_vabb1012)
                           if (kmslot(kdx-kch0+1) == 0) then
                           do nn = 1, nneed
                              xx = need(1,nn); yy = need(2,nn); ixv = 0.0d0
                              do u = 1, nub
                                 ixv = ixv + (-1d0 * t2b(a,u,i,k)) * H2C_ooov(xx,yy,l,u)
                              end do
                              idx2 = lk(1)
                              if (idx2/=0) then
                                 sgn = sign(1, idx2); idx2 = abs(idx2)
                              do jdet2 = off_vabb1012(idx2), off_vabb1012(idx2+1)-1
                                 u = vabb1012_excits(jdet2,5); v = vabb1012_excits(jdet2,6)
                                 ixv = ixv + (1d0 * (sgn*vabb1012_amps(jdet2))) * V2C_oovv(xx,yy,u,v)
                              end do
                              end if
                              do u = 1, nub
                                 ixv = ixv + (1d0 * t2b(a,u,i,l)) * H2C_ooov(xx,yy,k,u)
                              end do
                              IX(xx,yy) = ixv
                           end do
                           else
                           IX = reshape(kmRB(:,kmslot(kdx-kch0+1)), (/nob,nob/))
                           idx = lk(1)
                           if (idx/=0) then
                              sgn = sign(1, idx); idx = abs(idx)
                           do jdet = off_vabb1012(idx), off_vabb1012(idx+1)-1
                              u = vabb1012_excits(jdet,5); v = vabb1012_excits(jdet,6)
                              IX(:,:) = IX(:,:) + (1d0 * (sgn*vabb1012_amps(jdet))) * V2C_oovv(:,:,u,v)
                           end do
                           end if
                           end if
                           do nn = 1, nneed
                              mark(need(1,nn),need(2,nn)) = .false.
                           end do
                           do jr = rind%off(kdx), rind%off(kdx+1)-1
                              ird = rind%perm(jr); icls = kc0 + (ird-1)/n4abbb; idet = mod(ird-1, n4abbb) + 1
                              val = 0.0d0
                              idx = rp(ird)
                              if (idx/=0) then
                              select case (icls)
                              case (1)
                                 do jdet = off_vbbb31(idx), off_vbbb31(idx+1)-1
                                    y = vbbb31_excits(jdet,5); x = vbbb31_excits(jdet,6)
                                    val = val + vbbb31_amps(jdet) * ((-1)*IX(x,y) + (+1)*IX(y,x))
                                 end do
                              case (2)
                                 do jdet = off_vbbb31(idx), off_vbbb31(idx+1)-1
                                    y = vbbb31_excits(jdet,5); x = vbbb31_excits(jdet,6)
                                    val = val + vbbb31_amps(jdet) * ((-1)*IX(x,y) + (+1)*IX(y,x))
                                 end do
                                 val = -val
                              case (3)
                                 do jdet = off_vbbb31(idx), off_vbbb31(idx+1)-1
                                    y = vbbb31_excits(jdet,5); x = vbbb31_excits(jdet,6)
                                    val = val + vbbb31_amps(jdet) * ((-1)*IX(x,y) + (+1)*IX(y,x))
                                 end do
                              end select
                              end if
                              if (val /= 0.0d0) then
                                 !$omp atomic
                                 resid(idet) = resid(idet) + 0.5d0 * val
                              end if
                           end do
                        end do
                        !$omp end do
                        deallocate(IX, mark, need)
                        !$omp end parallel
                     end do
                     deallocate(kmnn, kmslot, kmdk, kmRB)
                     deallocate(RQ, rp)
                  end do

                  ! key-major: I3D_vooooo(bxyjlk) x tabb(acdiyx), 18 classes share IX(q)
                  kbat = max(1, min(18, 16777216 / max(1, n4abbb)))
                  do kc0 = 1, 18, kbat
                     kc1 = min(18, kc0 + kbat - 1)
                     nrd = (kc1 - kc0 + 1) * n4abbb
                     allocate(RQ(nrd,5), rp(nrd))
                     RQ(:,5) = 0   ! keeps a one-reader list from looking like the empty sentinel
                     do icls = kc0, kc1
                        ird0 = (icls - kc0) * n4abbb
                        select case (icls)
                        case (1)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,2); RQ(ird0+idet,2) = t4d_excits(idet,6); RQ(ird0+idet,3) = t4d_excits(idet,7); RQ(ird0+idet,4) = t4d_excits(idet,8);
                           end do
                        case (2)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,3); RQ(ird0+idet,2) = t4d_excits(idet,6); RQ(ird0+idet,3) = t4d_excits(idet,7); RQ(ird0+idet,4) = t4d_excits(idet,8);
                           end do
