                                    a = t4d_excits(idet,1); b = t4d_excits(idet,2); c = t4d_excits(idet,3); i = t4d_excits(idet,5);
                                    idx = pspace_find(key_vabb1210, nblk_vabb1210, pspace_key((/a,b,c,i/), 4, vdims_vabb1210, vchain_vabb1210))
                                    rp(ird) = idx
                                    if (idx/=0) then
