                                    a = t4d_excits(idet,1); b = t4d_excits(idet,2); c = t4d_excits(idet,3); l = t4d_excits(idet,8);
                                    idx = pspace_find(key_vabb1201, nblk_vabb1201, pspace_key((/a,b,c,l/), 4, vdims_vabb1201, vchain_vabb1201))
                                    rp(ird) = idx
                                    if (idx/=0) then
