                                       y = vbbb22_excits(jdet,5); x = vbbb22_excits(jdet,6)
                                       if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                    end do
                                    end if
                                 case (6)
                                    b = t4d_excits(idet,2); c = t4d_excits(idet,3); j = t4d_excits(idet,6); l = t4d_excits(idet,8);
                                    idx = pspace_find(key_vbbb22, nblk_vbbb22, pspace_key((/b,c,j,l/), 4, vdims_vbbb22, vchain_vbbb22))
                                    rp(ird) = idx
                                    if (idx/=0) then
                                    do jdet = off_vbbb22(idx), off_vbbb22(idx+1)-1
                                       y = vbbb22_excits(jdet,5); x = vbbb22_excits(jdet,6)
                                       if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                    end do
                                    end if
                                 case (7)
                                    c = t4d_excits(idet,3); d = t4d_excits(idet,4); j = t4d_excits(idet,6); k = t4d_excits(idet,7);
                                    idx = pspace_find(key_vbbb22, nblk_vbbb22, pspace_key((/c,d,j,k/), 4, vdims_vbbb22, vchain_vbbb22))
                                    rp(ird) = idx
                                    if (idx/=0) then
                                    do jdet = off_vbbb22(idx), off_vbbb22(idx+1)-1
                                       y = vbbb22_excits(jdet,5); x = vbbb22_excits(jdet,6)
                                       if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                    end do
                                    end if
                                 case (8)
                                    b = t4d_excits(idet,2); d = t4d_excits(idet,4); j = t4d_excits(idet,6); k = t4d_excits(idet,7);
                                    idx = pspace_find(key_vbbb22, nblk_vbbb22, pspace_key((/b,d,j,k/), 4, vdims_vbbb22, vchain_vbbb22))
                                    rp(ird) = idx
                                    if (idx/=0) then
                                    do jdet = off_vbbb22(idx), off_vbbb22(idx+1)-1
                                       y = vbbb22_excits(jdet,5); x = vbbb22_excits(jdet,6)
                                       if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                    end do
                                    end if
                                 case (9)
                                    b = t4d_excits(idet,2); c = t4d_excits(idet,3); j = t4d_excits(idet,6); k = t4d_excits(idet,7);
                                    idx = pspace_find(key_vbbb22, nblk_vbbb22, pspace_key((/b,c,j,k/), 4, vdims_vbbb22, vchain_vbbb22))
                                    rp(ird) = idx
                                    if (idx/=0) then
                                    do jdet = off_vbbb22(idx), off_vbbb22(idx+1)-1
                                       y = vbbb22_excits(jdet,5); x = vbbb22_excits(jdet,6)
                                       if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                    end do
                                    end if
                                 end select
                              end do
                           end if
                           ird = rind%perm(rind%off(kdx))
                           a = RQ(ird,1); d = RQ(ird,2); i = RQ(ird,3); l = RQ(ird,4);
                           lk(1) = pspace_find_sorted(key_vabb1111, nblk_vabb1111, (/a,d,i,l/), 4, vdims_vabb1111, vchain_vabb1111)
                           lk(2) = pspace_find_sorted(key_vaab1111, nblk_vaab1111, (/a,d,i,l/), 4, vdims_vaab1111, vchain_vaab1111)
                           if (kmslot(kdx-kch0+1) == 0) then
                           do nn = 1, nneed
                              xx = need(1,nn); yy = need(2,nn); ixv = 0.0d0
                              do u = 1, nob
                                 ixv = ixv + (-1d0 * t2b(a,d,i,u)) * H2C_ooov(u,xx,l,yy)
                              end do
                              do u = 1, nub
                                 ixv = ixv + (1d0 * t2b(a,u,i,l)) * H2C_vovv(d,xx,u,yy)
                              end do
                              do u = 1, noa
                                 ixv = ixv + (-1d0 * t2b(a,d,u,l)) * H2B_ooov(u,xx,i,yy)
                              end do
                              do u = 1, nua
                                 ixv = ixv + (1d0 * t2b(u,d,i,l)) * H2B_vovv(a,xx,u,yy)
                              end do
                              idx2 = lk(1)
                              if (idx2/=0) then
                                 sgn = sign(1, idx2); idx2 = abs(idx2)
                              do jdet2 = off_vabb1111(idx2), off_vabb1111(idx2+1)-1
                                 v = vabb1111_excits(jdet2,5); u = vabb1111_excits(jdet2,6)
                                 ixv = ixv + (1d0 * (sgn*vabb1111_amps(jdet2))) * V2C_oovv(u,xx,v,yy)
                              end do
                              end if
                              idx2 = lk(2)
                              if (idx2/=0) then
                                 sgn = sign(1, idx2); idx2 = abs(idx2)
                              do jdet2 = off_vaab1111(idx2), off_vaab1111(idx2+1)-1
                                 v = vaab1111_excits(jdet2,5); u = vaab1111_excits(jdet2,6)
                                 ixv = ixv + (1d0 * (sgn*vaab1111_amps(jdet2))) * V2B_oovv(u,xx,v,yy)
                              end do
                              end if
                              IX(xx,yy) = ixv
                           end do
                           else
                           IX = reshape(kmRB(:,kmslot(kdx-kch0+1)), (/nob,nub/))
                           idx = lk(1)
                           if (idx/=0) then
                              sgn = sign(1, idx); idx = abs(idx)
                           do jdet = off_vabb1111(idx), off_vabb1111(idx+1)-1
                              v = vabb1111_excits(jdet,5); u = vabb1111_excits(jdet,6)
                              IX(:,:) = IX(:,:) + (1d0 * (sgn*vabb1111_amps(jdet))) * V2C_oovv(u,:,v,:)
                           end do
                           end if
                           idx = lk(2)
                           if (idx/=0) then
                              sgn = sign(1, idx); idx = abs(idx)
                           do jdet = off_vaab1111(idx), off_vaab1111(idx+1)-1
                              v = vaab1111_excits(jdet,5); u = vaab1111_excits(jdet,6)
