                              select case (icls)
                              case (1)
                                 do jdet = off_vbbb22(idx), off_vbbb22(idx+1)-1
                                    y = vbbb22_excits(jdet,5); x = vbbb22_excits(jdet,6)
                                    val = val + vbbb22_amps(jdet) * ((+1)*IX(x,y))
                                 end do
                              case (2)
                                 do jdet = off_vbbb22(idx), off_vbbb22(idx+1)-1
                                    y = vbbb22_excits(jdet,5); x = vbbb22_excits(jdet,6)
                                    val = val + vbbb22_amps(jdet) * ((+1)*IX(x,y))
                                 end do
                                 val = -val
                              case (3)
                                 do jdet = off_vbbb22(idx), off_vbbb22(idx+1)-1
                                    y = vbbb22_excits(jdet,5); x = vbbb22_excits(jdet,6)
                                    val = val + vbbb22_amps(jdet) * ((+1)*IX(x,y))
                                 end do
                              case (4)
                                 do jdet = off_vbbb22(idx), off_vbbb22(idx+1)-1
                                    y = vbbb22_excits(jdet,5); x = vbbb22_excits(jdet,6)
                                    val = val + vbbb22_amps(jdet) * ((+1)*IX(x,y))
                                 end do
                                 val = -val
                              case (5)
                                 do jdet = off_vbbb22(idx), off_vbbb22(idx+1)-1
                                    y = vbbb22_excits(jdet,5); x = vbbb22_excits(jdet,6)
                                    val = val + vbbb22_amps(jdet) * ((+1)*IX(x,y))
                                 end do
                              case (6)
                                 do jdet = off_vbbb22(idx), off_vbbb22(idx+1)-1
                                    y = vbbb22_excits(jdet,5); x = vbbb22_excits(jdet,6)
                                    val = val + vbbb22_amps(jdet) * ((+1)*IX(x,y))
                                 end do
                                 val = -val
                              case (7)
                                 do jdet = off_vbbb22(idx), off_vbbb22(idx+1)-1
                                    y = vbbb22_excits(jdet,5); x = vbbb22_excits(jdet,6)
                                    val = val + vbbb22_amps(jdet) * ((+1)*IX(x,y))
                                 end do
                              case (8)
                                 do jdet = off_vbbb22(idx), off_vbbb22(idx+1)-1
                                    y = vbbb22_excits(jdet,5); x = vbbb22_excits(jdet,6)
                                    val = val + vbbb22_amps(jdet) * ((+1)*IX(x,y))
                                 end do
                                 val = -val
                              case (9)
                                 do jdet = off_vbbb22(idx), off_vbbb22(idx+1)-1
                                    y = vbbb22_excits(jdet,5); x = vbbb22_excits(jdet,6)
                                    val = val + vbbb22_amps(jdet) * ((+1)*IX(x,y))
                                 end do
                              end select
                              end if
                              if (val /= 0.0d0) then
                                 !$omp atomic
                                 resid(idet) = resid(idet) + 1d0 * val
                              end if
                           end do
                        end do
                        !$omp end do
                        deallocate(IX, mark, need)
                        !$omp end parallel
                     end do
                     deallocate(kmnn, kmslot, kmdk, kmRB)
                     deallocate(RQ, rp)
                  end do

                  ! key-major: I3D_vvooov(dcxlky) x tabb(aybixj), 9 classes share IX(q)
                  kbat = max(1, min(9, 16777216 / max(1, n4abbb)))
                  do kc0 = 1, 9, kbat
                     kc1 = min(9, kc0 + kbat - 1)
                     nrd = (kc1 - kc0 + 1) * n4abbb
                     allocate(RQ(nrd,5), rp(nrd))
                     RQ(:,5) = 0   ! keeps a one-reader list from looking like the empty sentinel
                     do icls = kc0, kc1
                        ird0 = (icls - kc0) * n4abbb
                        select case (icls)
                        case (1)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,3); RQ(ird0+idet,2) = t4d_excits(idet,2); RQ(ird0+idet,3) = t4d_excits(idet,7); RQ(ird0+idet,4) = t4d_excits(idet,6);
                           end do
                        case (2)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,4); RQ(ird0+idet,2) = t4d_excits(idet,2); RQ(ird0+idet,3) = t4d_excits(idet,7); RQ(ird0+idet,4) = t4d_excits(idet,6);
                           end do
                        case (3)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,4); RQ(ird0+idet,2) = t4d_excits(idet,3); RQ(ird0+idet,3) = t4d_excits(idet,7); RQ(ird0+idet,4) = t4d_excits(idet,6);
                           end do
                        case (4)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,3); RQ(ird0+idet,2) = t4d_excits(idet,2); RQ(ird0+idet,3) = t4d_excits(idet,8); RQ(ird0+idet,4) = t4d_excits(idet,6);
                           end do
                        case (5)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,4); RQ(ird0+idet,2) = t4d_excits(idet,2); RQ(ird0+idet,3) = t4d_excits(idet,8); RQ(ird0+idet,4) = t4d_excits(idet,6);
                           end do
                        case (6)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,4); RQ(ird0+idet,2) = t4d_excits(idet,3); RQ(ird0+idet,3) = t4d_excits(idet,8); RQ(ird0+idet,4) = t4d_excits(idet,6);
                           end do
                        case (7)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,3); RQ(ird0+idet,2) = t4d_excits(idet,2); RQ(ird0+idet,3) = t4d_excits(idet,8); RQ(ird0+idet,4) = t4d_excits(idet,7);
                           end do
                        case (8)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,4); RQ(ird0+idet,2) = t4d_excits(idet,2); RQ(ird0+idet,3) = t4d_excits(idet,8); RQ(ird0+idet,4) = t4d_excits(idet,7);
                           end do
                        case (9)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,4); RQ(ird0+idet,2) = t4d_excits(idet,3); RQ(ird0+idet,3) = t4d_excits(idet,8); RQ(ird0+idet,4) = t4d_excits(idet,7);
                           end do
                        end select
                     end do
                     call index_pspace(RQ, nrd, 4, (/1,2,3,4/), (/nub,nub,nob,nob/), (/.false.,.false.,.false.,.false./), rind)
                     allocate(kmnn(4096), kmslot(4096), kmdk(4096), kmRB(nob*nub,4096))
                     do kch0 = 1, rind%nblock, 4096
                        kch1 = min(rind%nblock, kch0 + 4096 - 1)
                        !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,kdx,idx,xx,yy,ixv,idx2,jdet2,jj2,lk,mark,need,nneed,nn,icls,ird,jr,sgn)
                        allocate(mark(nob,nub), need(2,nob*nub))
                        mark = .false.
                        !$omp do schedule(dynamic,8)
                        do kdx = kch0, kch1
                           nneed = 0
                           do jr = rind%off(kdx), rind%off(kdx+1)-1
                              ird = rind%perm(jr); icls = kc0 + (ird-1)/n4abbb; idet = mod(ird-1, n4abbb) + 1
                              select case (icls)
                              case (1)
                                 a = t4d_excits(idet,1); d = t4d_excits(idet,4); i = t4d_excits(idet,5); l = t4d_excits(idet,8);
                                 idx = pspace_find(key_vabb1111, nblk_vabb1111, pspace_key((/a,d,i,l/), 4, vdims_vabb1111, vchain_vabb1111))
                                 rp(ird) = idx
                                 if (idx/=0) then
                                 do jdet = off_vabb1111(idx), off_vabb1111(idx+1)-1
                                    y = vabb1111_excits(jdet,5); x = vabb1111_excits(jdet,6)
                                    if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                 end do
                                 end if
                              case (2)
                                 a = t4d_excits(idet,1); c = t4d_excits(idet,3); i = t4d_excits(idet,5); l = t4d_excits(idet,8);
                                 idx = pspace_find(key_vabb1111, nblk_vabb1111, pspace_key((/a,c,i,l/), 4, vdims_vabb1111, vchain_vabb1111))
                                 rp(ird) = idx
                                 if (idx/=0) then
                                 do jdet = off_vabb1111(idx), off_vabb1111(idx+1)-1
                                    y = vabb1111_excits(jdet,5); x = vabb1111_excits(jdet,6)
                                    if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                 end do
                                 end if
                              case (3)
                                 a = t4d_excits(idet,1); b = t4d_excits(idet,2); i = t4d_excits(idet,5); l = t4d_excits(idet,8);
                                 idx = pspace_find(key_vabb1111, nblk_vabb1111, pspace_key((/a,b,i,l/), 4, vdims_vabb1111, vchain_vabb1111))
                                 rp(ird) = idx
                                 if (idx/=0) then
                                 do jdet = off_vabb1111(idx), off_vabb1111(idx+1)-1
                                    y = vabb1111_excits(jdet,5); x = vabb1111_excits(jdet,6)
                                    if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                 end do
                                 end if
                              case (4)
                                 a = t4d_excits(idet,1); d = t4d_excits(idet,4); i = t4d_excits(idet,5); k = t4d_excits(idet,7);
                                 idx = pspace_find(key_vabb1111, nblk_vabb1111, pspace_key((/a,d,i,k/), 4, vdims_vabb1111, vchain_vabb1111))
                                 rp(ird) = idx
                                 if (idx/=0) then
                                 do jdet = off_vabb1111(idx), off_vabb1111(idx+1)-1
                                    y = vabb1111_excits(jdet,5); x = vabb1111_excits(jdet,6)
                                    if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                 end do
                                 end if
                              case (5)
