                           do nn = 1, nneed
                              mark(need(1,nn),need(2,nn)) = .false.
                           end do
                        end do
                        !$omp end do
                        deallocate(mark, need)
                        !$omp end parallel
                        ndk = 0
                        do kdx = kch0, kch1
                           kmslot(kdx-kch0+1) = 0
                           if (8*kmnn(kdx-kch0+1) >= nob*nub) then
                              ndk = ndk + 1; kmdk(ndk) = kdx; kmslot(kdx-kch0+1) = ndk
                           end if
                        end do
                        if (ndk > 0) then
