                                 case (8)
                                    a = t4d_excits(idet,1); c = t4d_excits(idet,3); j = t4d_excits(idet,6); k = t4d_excits(idet,7);
                                    idx = pspace_find(key_vabb1102, nblk_vabb1102, pspace_key((/a,c,j,k/), 4, vdims_vabb1102, vchain_vabb1102))
                                    rp(ird) = idx
