                                    idx = pspace_find(key_vabb1102, nblk_vabb1102, pspace_key((/a,b,j,k/), 4, vdims_vabb1102, vchain_vabb1102))
                                    rp(ird) = idx
                                    if (idx/=0) then
                                    do jdet = off_vabb1102(idx), off_vabb1102(idx+1)-1
                                       y = vabb1102_excits(jdet,5); x = vabb1102_excits(jdet,6)
                                       if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                    end do
                                    end if
                                 end select
                              end do
                           end if
                           ird = rind%perm(rind%off(kdx))
                           b = RQ(ird,1); d = RQ(ird,2); i = RQ(ird,3); l = RQ(ird,4);
                           lk(1) = pspace_find_sorted(key_vabb0211, nblk_vabb0211, (/b,d,i,l/), 4, vdims_vabb0211, vchain_vabb0211)
                           if (kmslot(kdx-kch0+1) == 0) then
                           do nn = 1, nneed
                              xx = need(1,nn); yy = need(2,nn); ixv = 0.0d0
                              do u = 1, nob
                                 ixv = ixv + (1d0 * t2c(b,d,l,u)) * H2B_ooov(xx,u,i,yy)
                              end do
                              do u = 1, nua
                                 ixv = ixv + (1d0 * t2b(u,d,i,l)) * H2B_ovvv(xx,b,u,yy)
                              end do
                              idx2 = lk(1)
                              if (idx2/=0) then
                                 sgn = sign(1, idx2); idx2 = abs(idx2)
                              do jdet2 = off_vabb0211(idx2), off_vabb0211(idx2+1)-1
                                 v = vabb0211_excits(jdet2,5); u = vabb0211_excits(jdet2,6)
                                 ixv = ixv + (1d0 * (sgn*vabb0211_amps(jdet2))) * V2B_oovv(xx,u,v,yy)
                              end do
                              end if
                              do u = 1, nua
                                 ixv = ixv + (-1d0 * t2b(u,b,i,l)) * H2B_ovvv(xx,d,u,yy)
                              end do
                              IX(xx,yy) = ixv
