                                    val = val + vabb1102_amps(jdet) * ((-1)*IX(x,y))
                                 end do
                                 val = -val
                              case (2)
                                 do jdet = off_vabb1102(idx), off_vabb1102(idx+1)-1
                                    y = vabb1102_excits(jdet,5); x = vabb1102_excits(jdet,6)
                                    val = val + vabb1102_amps(jdet) * ((-1)*IX(x,y))
