                        end do
                        !$omp end do
                        deallocate(IX, mark, need)
                        !$omp end parallel
                     end do
                     deallocate(kmnn, kmslot, kmdk, kmRB)
                     deallocate(RQ, rp)
                  end do

                  ! key-major: I3C_vovvoo(axdyjl) x tabb(ybcixk), 9 classes share IX(q)
                  kbat = max(1, min(9, 16777216 / max(1, n4abbb)))
                  do kc0 = 1, 9, kbat
                     kc1 = min(9, kc0 + kbat - 1)
                     nrd = (kc1 - kc0 + 1) * n4abbb
                     allocate(RQ(nrd,5), rp(nrd))
                     RQ(:,5) = 0   ! keeps a one-reader list from looking like the empty sentinel
                     do icls = kc0, kc1
                        ird0 = (icls - kc0) * n4abbb
                        select case (icls)
                        case (1)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,1); RQ(ird0+idet,2) = t4d_excits(idet,2); RQ(ird0+idet,3) = t4d_excits(idet,6); RQ(ird0+idet,4) = t4d_excits(idet,7);
                           end do
                        case (2)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,1); RQ(ird0+idet,2) = t4d_excits(idet,3); RQ(ird0+idet,3) = t4d_excits(idet,6); RQ(ird0+idet,4) = t4d_excits(idet,7);
                           end do
                        case (3)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,1); RQ(ird0+idet,2) = t4d_excits(idet,4); RQ(ird0+idet,3) = t4d_excits(idet,6); RQ(ird0+idet,4) = t4d_excits(idet,7);
                           end do
                        case (4)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,1); RQ(ird0+idet,2) = t4d_excits(idet,2); RQ(ird0+idet,3) = t4d_excits(idet,6); RQ(ird0+idet,4) = t4d_excits(idet,8);
                           end do
                        case (5)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,1); RQ(ird0+idet,2) = t4d_excits(idet,3); RQ(ird0+idet,3) = t4d_excits(idet,6); RQ(ird0+idet,4) = t4d_excits(idet,8);
                           end do
                        case (6)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,1); RQ(ird0+idet,2) = t4d_excits(idet,4); RQ(ird0+idet,3) = t4d_excits(idet,6); RQ(ird0+idet,4) = t4d_excits(idet,8);
                           end do
                        case (7)
                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,1); RQ(ird0+idet,2) = t4d_excits(idet,2); RQ(ird0+idet,3) = t4d_excits(idet,7); RQ(ird0+idet,4) = t4d_excits(idet,8);
                           end do
