                                 do jdet = off_vabb0211(idx), off_vabb0211(idx+1)-1
                                    y = vabb0211_excits(jdet,5); x = vabb0211_excits(jdet,6)
                                    if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
