                           do idet = 1, n4abbb
                              RQ(ird0+idet,1) = t4d_excits(idet,2); RQ(ird0+idet,2) = t4d_excits(idet,4); RQ(ird0+idet,3) = t4d_excits(idet,7); RQ(ird0+idet,4) = t4d_excits(idet,8);
