                                    y = vaab1111_excits(jdet,5); x = vaab1111_excits(jdet,6)
                                    if (.not. mark(x,y)) then; mark(x,y) = .true.; nneed = nneed + 1; need(1,nneed) = x; need(2,nneed) = y; end if
                                 end do
